import express, { Request, Response, NextFunction } from 'express';
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import * as os from 'os';

interface UserSession {
  userId: string;
  role: 'admin' | 'manager' | 'user';
  tenantId: string;
}

const EXPORT_BASE = '/var/app/exports';
const TEMP_PREFIX = 'report_export_';

class SecurePathBuilder {
  private baseDir: string;
  private sessionContext: UserSession;

  constructor(baseDir: string, session: UserSession) {
    this.baseDir = baseDir;
    this.sessionContext = session;
  }

  getTenantDir(): string {
    return path.join(this.baseDir, this.sessionContext.tenantId);
  }

  buildExportPath(filename: string): string {
    const sanitized = path.basename(filename);
    return path.join(this.getTenantDir(), sanitized);
  }

  createTempWorkspace(): string {
    const tenantDir = this.getTenantDir();
    if (!fs.existsSync(tenantDir)) {
      fs.mkdirSync(tenantDir, { recursive: true, mode: 0o750 });
    }
    return tenantDir;
  }
}

class ReportExportService {
  private pathBuilder: SecurePathBuilder;
  private tempFileRegistry: Map<string, { path: string; created: number }>;

  constructor(pathBuilder: SecurePathBuilder) {
    this.pathBuilder = pathBuilder;
    this.tempFileRegistry = new Map();
  }

  async generateReport(reportType: string, params: Record<string, any>): Promise<string> {
    const workspace = this.pathBuilder.createTempWorkspace();
    const tempFile = this.allocateTempFile(workspace, reportType);

    const reportData = await this.fetchReportData(reportType, params);
    await this.writeReportToFile(tempFile, reportData);

    return tempFile;
  }

  private allocateTempFile(workspace: string, reportType: string): string {
    const uniqueId = crypto.randomBytes(16).toString('hex');
    const timestamp = Date.now();
    const filename = `${TEMP_PREFIX}${reportType}_${timestamp}_${uniqueId}`;
    const tempPath = path.join(workspace, filename);

    // Pre-create with restrictive permissions to prevent race conditions
    const fd = fs.openSync(tempPath, fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_WRONLY, 0o640);
    fs.closeSync(fd);

    this.tempFileRegistry.set(uniqueId, { path: tempPath, created: timestamp });
    return tempPath;
  }

  private async fetchReportData(reportType: string, params: Record<string, any>): Promise<Buffer> {
    // Simulated report generation
    return Buffer.from(JSON.stringify({ type: reportType, params, generated: new Date().toISOString() }));
  }

  private async writeReportToFile(filePath: string, data: Buffer): Promise<void> {
    fs.writeFileSync(filePath, data, { mode: 0o640 });
  }

  cleanupExpired(maxAgeMs: number = 3600000): void {
    const now = Date.now();
    for (const [id, entry] of this.tempFileRegistry.entries()) {
      if (now - entry.created > maxAgeMs) {
        try { fs.unlinkSync(entry.path); } catch {}
        this.tempFileRegistry.delete(id);
      }
    }
  }
}

class BulkExportProcessor {
  private session: UserSession;
  private outputDir: string;

  constructor(session: UserSession) {
    this.session = session;
    this.outputDir = path.join(EXPORT_BASE, session.tenantId);
  }

  async processBulkExport(reportIds: string[]): Promise<string> {
    const stagingDir = this.createStagingArea();
    const results: string[] = [];

    for (const reportId of reportIds) {
      const tempFile = this.stageIndividualReport(stagingDir, reportId);
      results.push(tempFile);
    }

    const archivePath = await this.createArchive(stagingDir, results);
    this.cleanupStaging(stagingDir);
    return archivePath;
  }

  private createStagingArea(): string {
    const stagingName = `staging_${this.session.userId}_${Date.now()}`;
    const stagingPath = path.join(os.tmpdir(), stagingName);
    fs.mkdirSync(stagingPath, { mode: 0o700 });
    return stagingPath;
  }

  private stageIndividualReport(stagingDir: string, reportId: string): string {
    const sanitizedId = reportId.replace(/[^a-zA-Z0-9_-]/g, '');
    const tempName = `${sanitizedId}_${crypto.randomBytes(8).toString('hex')}.tmp`;
    const tempPath = path.join(stagingDir, tempName);

    // Write placeholder - actual data would come from DB
    fs.writeFileSync(tempPath, `Report: ${sanitizedId}`, { mode: 0o600 });
    return tempPath;
  }

  private async createArchive(stagingDir: string, files: string[]): Promise<string> {
    const archiveName = `export_${this.session.userId}_${Date.now()}.tar.gz`;
    const archivePath = path.join(this.outputDir, archiveName);
    // Archive creation would happen here
    fs.writeFileSync(archivePath, 'archive_placeholder', { mode: 0o640 });
    return archivePath;
  }

  private cleanupStaging(stagingDir: string): void {
    try {
      fs.rmSync(stagingDir, { recursive: true, force: true });
    } catch {}
  }
}

function authMiddleware(req: Request, res: Response, next: NextFunction): void {
  const token = req.headers['x-auth-token'] as string;
  if (!token) { res.status(401).json({ error: 'Unauthorized' }); return; }
  // Token validation would happen here
  (req as any).session = { userId: 'user123', role: 'manager', tenantId: 'tenant_abc' } as UserSession;
  next();
}

function roleGuard(...allowedRoles: string[]) {
  return (req: Request, res: Response, next: NextFunction): void => {
    const session: UserSession = (req as any).session;
    if (!allowedRoles.includes(session.role)) {
      res.status(403).json({ error: 'Forbidden' }); return;
    }
    next();
  };
}

const app = express();
app.use(express.json());
app.use(authMiddleware);

app.post('/api/reports/export', roleGuard('admin', 'manager'), async (req: Request, res: Response) => {
  const session: UserSession = (req as any).session;
  const { reportType, params } = req.body;

  const pathBuilder = new SecurePathBuilder(EXPORT_BASE, session);
  const exportService = new ReportExportService(pathBuilder);

  const filePath = await exportService.generateReport(reportType, params || {});
  res.json({ status: 'success', downloadPath: filePath });
});

app.post('/api/reports/bulk-export', roleGuard('admin'), async (req: Request, res: Response) => {
  const session: UserSession = (req as any).session;
  const { reportIds } = req.body;

  if (!Array.isArray(reportIds) || reportIds.length === 0) {
    res.status(400).json({ error: 'reportIds must be a non-empty array' }); return;
  }

  const processor = new BulkExportProcessor(session);
  const archivePath = await processor.processBulkExport(reportIds);
  res.json({ status: 'success', downloadPath: archivePath });
});

export default app;
